//! Deterministic fixture generation (addendum §10).
//!
//! `fixtures/small-repo` is committed. `fixtures/large-repo` is generated by
//! [`generate_large_repo`] (10k+ files, a 24-level deep tree, one directory
//! with more entries than a listing page, ignored directories) and its output
//! is git-ignored; `examples/generate_large_repo.rs` writes it on demand and
//! the integration tests generate it under `target/`.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};

/// Bump when the layout changes so cached generations are refreshed.
pub const LARGE_REPO_LAYOUT_VERSION: u32 = 1;
/// Marker file written last; its content is the layout version.
pub const LARGE_REPO_MARKER: &str = ".gritty-fixture";

/// Directory with more entries than one listing page (`MAX_PAGE_SIZE`).
pub const BULK_DIRECTORY: &str = "bulk";
pub const BULK_ENTRIES: usize = 5_200;
/// Root of the deep chain `deep/level_01/.../level_24/leaf.rs`.
pub const DEEP_DIRECTORY: &str = "deep";
pub const DEEP_LEVELS: u32 = 24;
pub const SRC_MODULES: usize = 50;
pub const FILES_PER_MODULE: usize = 100;
pub const DOC_FILES: usize = 200;
pub const NODE_MODULES_PACKAGES: usize = 20;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LargeRepoSummary {
    pub files: u64,
    pub directories: u64,
    pub max_depth: u32,
}

/// Names of the root entries the generator creates, sorted the way a listing
/// returns them (directories first, then by name).
pub const LARGE_REPO_ROOT_ENTRIES: &[&str] = &[
    ".git",
    "bulk",
    "deep",
    "dist",
    "docs",
    "node_modules",
    "src",
    "target",
    ".gritty-fixture",
    "Cargo.toml",
    "README.md",
    "package.json",
];

/// (Re)generate the large fixture at `dir`. The directory is removed first.
pub fn generate_large_repo(dir: &Path) -> io::Result<LargeRepoSummary> {
    if dir.exists() {
        fs::remove_dir_all(dir)?;
    }
    fs::create_dir_all(dir)?;
    // Write through the canonical base so a relative or `..`-containing `dir`
    // is resolved once, and so the deep chain (which exceeds the legacy Windows
    // MAX_PATH in most checkouts) is created through a verbatim-prefixed path.
    let base = fs::canonicalize(dir)?;
    let mut generator = Generator::new(&base)?;

    generator.file(
        "README.md",
        "# large-repo\n\nGenerated fixture; do not edit.\n",
    )?;
    generator.file(
        "package.json",
        "{ \"name\": \"large-repo\", \"private\": true }\n",
    )?;
    generator.file("Cargo.toml", "[package]\nname = \"large-repo\"\n")?;

    generator.dir("src")?;
    for module in 0..SRC_MODULES {
        let dir = format!("src/module_{module:02}");
        generator.dir(&dir)?;
        for file in 0..FILES_PER_MODULE {
            generator.file(
                &format!("{dir}/file_{file:03}.ts"),
                "export const value = 1;\n",
            )?;
        }
    }
    generator.dir("docs")?;
    for doc in 0..DOC_FILES {
        generator.file(&format!("docs/guide_{doc:03}.md"), "# guide\n")?;
    }
    generator.dir(BULK_DIRECTORY)?;
    for entry in 0..BULK_ENTRIES {
        generator.file(&format!("{BULK_DIRECTORY}/entry_{entry:04}.txt"), "bulk\n")?;
    }
    let mut deep = PathBuf::from(DEEP_DIRECTORY);
    generator.dir(DEEP_DIRECTORY)?;
    for level in 1..=DEEP_LEVELS {
        deep.push(format!("level_{level:02}"));
        generator.dir(&deep.to_string_lossy())?;
        generator.file(&format!("{}/note.md", deep.to_string_lossy()), "deep\n")?;
    }
    generator.file(
        &format!("{}/leaf.rs", deep.to_string_lossy()),
        "fn leaf() {}\n",
    )?;
    generator.dir("node_modules")?;
    for package in 0..NODE_MODULES_PACKAGES {
        let dir = format!("node_modules/pkg_{package:02}");
        generator.dir(&dir)?;
        generator.file(&format!("{dir}/package.json"), "{}\n")?;
        generator.file(&format!("{dir}/index.js"), "module.exports = {};\n")?;
    }
    generator.dir("target")?;
    generator.dir("target/debug")?;
    for object in 0..20 {
        generator.file(&format!("target/debug/build_{object:02}.o"), "OBJ\n")?;
    }
    generator.dir("dist")?;
    for bundle in 0..10 {
        generator.file(&format!("dist/bundle_{bundle}.js"), "!function(){}();\n")?;
    }
    generator.dir(".git")?;
    generator.file(".git/HEAD", "ref: refs/heads/main\n")?;
    generator.file(".git/config", "[core]\n\tbare = false\n")?;

    generator.file(LARGE_REPO_MARKER, &LARGE_REPO_LAYOUT_VERSION.to_string())?;
    Ok(generator.summary(DEEP_LEVELS + 1))
}

/// `true` when `dir` holds a complete generation of the current layout.
pub fn large_repo_is_current(dir: &Path) -> bool {
    fs::read_to_string(dir.join(LARGE_REPO_MARKER))
        .is_ok_and(|content| content.trim() == LARGE_REPO_LAYOUT_VERSION.to_string())
}

struct Generator<'a> {
    root: &'a Path,
    files: u64,
    directories: u64,
}

impl<'a> Generator<'a> {
    fn new(root: &'a Path) -> io::Result<Self> {
        fs::create_dir_all(root)?;
        Ok(Self {
            root,
            files: 0,
            directories: 0,
        })
    }

    fn dir(&mut self, relative: &str) -> io::Result<()> {
        fs::create_dir(self.root.join(relative))?;
        self.directories += 1;
        Ok(())
    }

    fn file(&mut self, relative: &str, content: &str) -> io::Result<()> {
        fs::write(self.root.join(relative), content)?;
        self.files += 1;
        Ok(())
    }

    fn summary(&self, max_depth: u32) -> LargeRepoSummary {
        LargeRepoSummary {
            files: self.files,
            directories: self.directories,
            max_depth,
        }
    }
}

// ---------------------------------------------------------------------------
// weird-files (T030, addendum §10.3)
// ---------------------------------------------------------------------------

/// Committed fixture directory name under `fixtures/`.
pub const WEIRD_FILES_DIR: &str = "weird-files";
/// Directory inside the fixture that holds generated (git-ignored) members.
pub const WEIRD_GENERATED_DIR: &str = "generated";
/// Generated text file above the large-file threshold.
pub const WEIRD_LARGE_TEXT: &str = "generated/large-text.txt";
pub const WEIRD_LARGE_TEXT_BYTES: u64 = 12 * 1024 * 1024;
/// Generated file with no permissions (Unix only); reads must fail cleanly.
pub const WEIRD_DENIED: &str = "generated/denied.txt";
/// Symlinks of the fixture: `(link, target)`, targets relative to the link's
/// directory. Recreated by [`stage_weird_files`] on every platform that allows
/// it, so tests do not depend on how the checkout materialized them.
pub const WEIRD_LINKS: &[(&str, &str, bool)] = &[
    ("links/to-readme", "../readme.md", false),
    ("links/to-unicode", "../unicode", true),
    ("links/broken", "../missing-target", false),
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WeirdFilesSummary {
    /// Regular files copied from the committed fixture.
    pub copied_files: u64,
    /// Symlinks created (fewer than `WEIRD_LINKS` when the platform refused).
    pub symlinks: u64,
    pub large_text_bytes: u64,
    /// The permission-denied file exists with mode `000` (Unix only).
    pub denied_created: bool,
}

/// Copy the committed `weird-files` fixture at `committed` into `dest`
/// (removed first), recreate its symlinks from [`WEIRD_LINKS`] and add the
/// generated members ([`augment_weird_files`]). Tests write into the staged
/// copy, never into the committed fixture.
pub fn stage_weird_files(committed: &Path, dest: &Path) -> io::Result<WeirdFilesSummary> {
    if dest.exists() {
        remove_dir_all_forced(dest)?;
    }
    fs::create_dir_all(dest)?;
    let dest = fs::canonicalize(dest)?;
    let mut copied_files = 0;
    copy_tree(committed, &dest, Path::new(""), &mut copied_files)?;
    let mut symlinks = 0;
    for (link, target, is_dir) in WEIRD_LINKS {
        let link = dest.join(link);
        if let Some(parent) = link.parent() {
            fs::create_dir_all(parent)?;
        }
        if create_symlink(Path::new(target), &link, *is_dir)? {
            symlinks += 1;
        }
    }
    let (large_text_bytes, denied_created) = augment_weird_files(&dest)?;
    Ok(WeirdFilesSummary {
        copied_files,
        symlinks,
        large_text_bytes,
        denied_created,
    })
}

/// Add the generated members to a `weird-files` tree: `generated/large-text.txt`
/// (deterministic, above the large-file threshold) and `generated/denied.txt`
/// (mode `000` on Unix). Returns `(large text size, denied created)`.
pub fn augment_weird_files(dir: &Path) -> io::Result<(u64, bool)> {
    use std::io::Write;

    let generated = dir.join(WEIRD_GENERATED_DIR);
    fs::create_dir_all(&generated)?;
    let large = dir.join(WEIRD_LARGE_TEXT);
    let mut out = io::BufWriter::new(fs::File::create(&large)?);
    let mut written = 0u64;
    let mut line = 0u64;
    while written < WEIRD_LARGE_TEXT_BYTES {
        let text = format!(
            "line {line:08}: the quick brown fox jumps over the lazy dog {}\n",
            "0123456789".repeat(3)
        );
        out.write_all(text.as_bytes())?;
        written += text.len() as u64;
        line += 1;
    }
    out.flush()?;
    drop(out);

    let denied = dir.join(WEIRD_DENIED);
    // Make it writable first in case a previous generation left it at 000.
    let _ = set_mode(&denied, 0o600);
    fs::write(&denied, "you should not be able to read this\n")?;
    let denied_created = set_mode(&denied, 0o000).is_ok();
    Ok((written, denied_created))
}

fn copy_tree(
    src_root: &Path,
    dest_root: &Path,
    relative: &Path,
    files: &mut u64,
) -> io::Result<()> {
    let src = src_root.join(relative);
    for entry in fs::read_dir(&src)? {
        let entry = entry?;
        let name = entry.file_name();
        let child = relative.join(&name);
        // Symlinks and generated members are recreated, never copied.
        if child.starts_with("links") || child.starts_with(WEIRD_GENERATED_DIR) {
            continue;
        }
        let file_type = entry.file_type()?;
        if file_type.is_symlink() {
            continue;
        }
        let target = dest_root.join(&child);
        if file_type.is_dir() {
            fs::create_dir_all(&target)?;
            copy_tree(src_root, dest_root, &child, files)?;
        } else if file_type.is_file() {
            fs::copy(entry.path(), &target)?;
            *files += 1;
        }
    }
    Ok(())
}

/// `Ok(false)` when the platform refuses symlinks (Windows without Developer
/// Mode or elevation); every other failure is an error.
fn create_symlink(target: &Path, link: &Path, target_is_dir: bool) -> io::Result<bool> {
    #[cfg(unix)]
    let result = {
        let _ = target_is_dir;
        std::os::unix::fs::symlink(target, link)
    };
    #[cfg(windows)]
    let result = if target_is_dir {
        std::os::windows::fs::symlink_dir(target, link)
    } else {
        std::os::windows::fs::symlink_file(target, link)
    };
    match result {
        Ok(()) => Ok(true),
        Err(error) if error.kind() == io::ErrorKind::PermissionDenied => Ok(false),
        Err(error) => Err(error),
    }
}

#[cfg(unix)]
fn set_mode(path: &Path, mode: u32) -> io::Result<()> {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(mode))
}

#[cfg(not(unix))]
fn set_mode(_path: &Path, _mode: u32) -> io::Result<()> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "permission bits are Unix-only",
    ))
}

/// `remove_dir_all` that also handles the mode-000 file the generator leaves
/// behind (removing it needs only write permission on its directory, which
/// holds on Unix; on other platforms the read-only flag is cleared first).
fn remove_dir_all_forced(dir: &Path) -> io::Result<()> {
    let denied = dir.join(WEIRD_DENIED);
    if denied.exists() {
        let _ = set_mode(&denied, 0o600);
        if let Ok(metadata) = fs::metadata(&denied) {
            let mut permissions = metadata.permissions();
            #[allow(clippy::permissions_set_readonly_false)]
            permissions.set_readonly(false);
            let _ = fs::set_permissions(&denied, permissions);
        }
    }
    fs::remove_dir_all(dir)
}
